[color=#c792ea]use[/color] std::fmt;

#[lb]derive([color=#ffcb6b]Debug[/color], [color=#ffcb6b]PartialEq[/color])[rb]
[color=#c792ea]enum[/color] [color=#ffcb6b]CrabError[/color] {
