}

[color=#c792ea]impl[/color] fmt::[color=#ffcb6b]Display[/color] [color=#c792ea]for[/color] [color=#ffcb6b]CrabError[/color] {
    [color=#c792ea]fn[/color] fmt(&[color=#c792ea]self[/color], f: &[color=#c792ea]mut[/color] fmt::[color=#ffcb6b]Formatter[/color]) -> fmt::[color=#ffcb6b]Result[/color] {
        [color=#c792ea]match[/color] [color=#c792ea]self[/color] {
            [color=#ffcb6b]CrabError[/color]::[color=#ffcb6b]Empty[/color] => [color=#82aaff]write[/color]!(f, [color=#c3e88d]"empty input"[/color]),
            [color=#ffcb6b]CrabError[/color]::[color=#ffcb6b]NotANumber[/color] => [color=#82aaff]write[/color]!(f, [color=#c3e88d]"not a number"[/color]),
            [color=#ffcb6b]CrabError[/color]::[color=#ffcb6b]TooBig[/color](n) => [color=#82aaff]write[/color]!(f, [color=#c3e88d]"{} is too big (max 100)"[/color], n),
        }
    }
}

[color=#c792ea]fn[/color] parse_shells(text: &str) -> [color=#ffcb6b]Result[/color]<u32, [color=#ffcb6b]CrabError[/color]> {
    [color=#c792ea]let[/color] text = text.trim();
    [color=#c792ea]if[/color] text.is_empty() {
        [color=#c792ea]return[/color] [color=#ffcb6b]Err[/color]([color=#ffcb6b]CrabError[/color]::[color=#ffcb6b]Empty[/color]);
    }
    [color=#c792ea]let[/color] n = [color=#c792ea]match[/color] text.parse::<u32>() {
        [color=#ffcb6b]Ok[/color](n) => n,
        [color=#ffcb6b]Err[/color](_) => [color=#c792ea]return[/color] [color=#ffcb6b]Err[/color]([color=#ffcb6b]CrabError[/color]::[color=#ffcb6b]NotANumber[/color]),
    };
    [color=#c792ea]if[/color] n > [color=#f78c6c]100[/color] {
        [color=#c792ea]return[/color] [color=#ffcb6b]Err[/color]([color=#ffcb6b]CrabError[/color]::[color=#ffcb6b]TooBig[/color](n));
    }
    [color=#ffcb6b]Ok[/color](n)
}

[color=#c792ea]fn[/color] total_shells(a: &str, b: &str) -> [color=#ffcb6b]Result[/color]<u32, [color=#ffcb6b]CrabError[/color]> {
    [color=#c792ea]let[/color] x = parse_shells(a)?;
    [color=#c792ea]let[/color] y = parse_shells(b)?;
    [color=#ffcb6b]Ok[/color](x + y)
}

[color=#c792ea]fn[/color] report(a: &str, b: &str) -> [color=#ffcb6b]String[/color] {
    [color=#c792ea]match[/color] total_shells(a, b) {
        [color=#ffcb6b]Ok[/color](n) => [color=#82aaff]format[/color]!([color=#c3e88d]"Total: {}"[/color], n),
        [color=#ffcb6b]Err[/color](e) => [color=#82aaff]format[/color]!([color=#c3e88d]"Error: {}"[/color], e),
    }
}

[color=#c792ea]fn[/color] main() {
    [color=#82aaff]println[/color]!([color=#c3e88d]"{}"[/color], report([color=#c3e88d]"3"[/color], [color=#c3e88d]"4"[/color]));
    [color=#82aaff]println[/color]!([color=#c3e88d]"{}"[/color], report([color=#c3e88d]"3"[/color], [color=#c3e88d]"x"[/color]));
    [color=#82aaff]println[/color]!([color=#c3e88d]"{}"[/color], report([color=#c3e88d]""[/color], [color=#c3e88d]"4"[/color]));
