[color=#c792ea]impl[/color] [color=#ffcb6b]Describe[/color] [color=#c792ea]for[/color] [color=#ffcb6b]Hero[/color] {
    [color=#c792ea]fn[/color] title(&[color=#c792ea]self[/color]) -> [color=#ffcb6b]String[/color] {
        [color=#c792ea]self[/color].name.clone()
    }
}

[color=#c792ea]enum[/color] [color=#ffcb6b]Move[/color] {
    [color=#ffcb6b]Claw[/color],
    [color=#ffcb6b]Pinch[/color](u32),
    [color=#ffcb6b]Retreat[/color],
}

[color=#c792ea]fn[/color] damage(m: &[color=#ffcb6b]Move[/color]) -> u32 {
    [color=#c792ea]match[/color] m {
        [color=#ffcb6b]Move[/color]::[color=#ffcb6b]Claw[/color] => [color=#f78c6c]5[/color],
        [color=#ffcb6b]Move[/color]::[color=#ffcb6b]Pinch[/color](n) => n * [color=#f78c6c]2[/color],
        [color=#ffcb6b]Move[/color]::[color=#ffcb6b]Retreat[/color] => [color=#f78c6c]0[/color],
    }
}

[color=#c792ea]fn[/color] total_damage(moves: &[lb][color=#ffcb6b]Move[/color][rb]) -> u32 {
    moves.iter().map(|m| damage(m)).sum()
}

[color=#c792ea]fn[/color] count_big_hits(moves: &[lb][color=#ffcb6b]Move[/color][rb]) -> usize {
    moves.iter().filter(|m| damage(m) >= [color=#f78c6c]10[/color]).count()
}

[color=#c792ea]fn[/color] parse_move(text: &str) -> [color=#ffcb6b]Result[/color]<[color=#ffcb6b]Move[/color], [color=#ffcb6b]String[/color]> {
    [color=#c792ea]let[/color] text = text.trim();
    [color=#c792ea]if[/color] text == [color=#c3e88d]"claw"[/color] {
        [color=#c792ea]return[/color] [color=#ffcb6b]Ok[/color]([color=#ffcb6b]Move[/color]::[color=#ffcb6b]Claw[/color]);
    }
    [color=#c792ea]if[/color] text == [color=#c3e88d]"retreat"[/color] {
        [color=#c792ea]return[/color] [color=#ffcb6b]Ok[/color]([color=#ffcb6b]Move[/color]::[color=#ffcb6b]Retreat[/color]);
    }
    [color=#c792ea]if[/color] [color=#c792ea]let[/color] [color=#ffcb6b]Some[/color](rest) = text.strip_prefix([color=#c3e88d]"pinch "[/color]) {
        [color=#c792ea]return[/color] [color=#c792ea]match[/color] rest.trim().parse::<u32>() {
            [color=#ffcb6b]Ok[/color](n) => [color=#ffcb6b]Ok[/color]([color=#ffcb6b]Move[/color]::[color=#ffcb6b]Pinch[/color](n)),
            [color=#ffcb6b]Err[/color](_) => [color=#ffcb6b]Err[/color]([color=#82aaff]format[/color]!([color=#c3e88d]"bad pinch power: {}"[/color], rest)),
        };
    }
    [color=#ffcb6b]Err[/color]([color=#82aaff]format[/color]!([color=#c3e88d]"unknown move: {}"[/color], text))
}

[color=#c792ea]fn[/color] parse_battle(script: &str) -> [color=#ffcb6b]Result[/color]<[color=#ffcb6b]Vec[/color]<[color=#ffcb6b]Move[/color]>, [color=#ffcb6b]String[/color]> {
    [color=#c792ea]let[/color] [color=#c792ea]mut[/color] moves = [color=#ffcb6b]Vec[/color]::new();
    [color=#c792ea]for[/color] piece [color=#c792ea]in[/color] script.split([color=#c3e88d]','[/color]) {
        [color=#c792ea]let[/color] m = parse_move(piece)?;
        moves.push(m);
    }
    [color=#ffcb6b]Ok[/color](moves)
}

[color=#c792ea]fn[/color] main() {
    [color=#c792ea]let[/color] hero = [color=#ffcb6b]Hero[/color]::new([color=#c3e88d]"Pinch"[/color]);
    [color=#82aaff]println[/color]!([color=#c3e88d]"{}"[/color], hero.banner());
    [color=#c792ea]match[/color] parse_battle([color=#c3e88d]"claw, pinch 4, retreat"[/color]) {
        [color=#ffcb6b]Ok[/color](moves) => [color=#82aaff]println[/color]!([color=#c3e88d]"Damage: {}"[/color], total_damage(&moves)),
        [color=#ffcb6b]Err[/color](e) => [color=#82aaff]println[/color]!([color=#c3e88d]"Bad script: {}"[/color], e),
    }
}

